import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as Primitive from "@radix-ui/react-popover";
import type { ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./shared/popover-content.css";
import "./popover.css";

export const Popover = Primitive.Root;
export const PopoverTrigger = Primitive.Trigger;
export const PopoverClose = Primitive.Close;
export const PopoverAnchor = Primitive.Anchor;

export function PopoverContent({
  className,
  sideOffset = 8,
  collisionPadding = 16,
  arrow = false,
  children,
  ...props
}: ComponentProps<typeof Primitive.Content> & {
  /** Points at the trigger and follows collision shifts. */
  arrow?: boolean;
}) {
  return (
    <Primitive.Portal>
      <Primitive.Content
        data-slot="popover-content"
        sideOffset={sideOffset}
        collisionPadding={collisionPadding}
        className={cn(
          "z-50 w-80 max-w-[calc(100vw-2rem)] max-h-[var(--radix-popover-content-available-height)] overflow-y-auto rounded-surface border border-border bg-elevated p-3.5 text-sm text-foreground shadow-overlay outline-none",
          arrow && "overflow-visible",
          className,
        )}
        {...props}
      >
        {children}
        {arrow && <Primitive.Arrow data-slot="popover-arrow" width={14} height={7} />}
      </Primitive.Content>
    </Primitive.Portal>
  );
}

/* Shared by date-input.tsx, popover.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="popover-content"] {
    transform-origin: var(--radix-popover-content-transform-origin);
  }
  [data-slot="popover-content"][data-state="open"] {
    animation: caliper-dialog-enter var(--duration-normal) var(--ease-settle);
  }
  [data-slot="popover-content"][data-state="closed"] {
    animation: caliper-fade-out var(--duration-fast) var(--ease-in) forwards;
    pointer-events: none;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="popover-content"] {
      animation: none;
    }
    /* Preserve the exit name for Radix Presence's completion matcher, including
       a preference changed during exit. No visual motion or unmount timer. */
    [data-slot="popover-content"][data-state="closed"] {
      animation: caliper-fade-out var(--duration-instant) var(--ease-in) forwards !important;
    }
  }
}

[data-slot="popover-content"] {
  background-color: var(--elevated-glass);
  border-color: color-mix(in srgb, var(--edge-light) 45%, var(--border));
  backdrop-filter: blur(var(--blur-overlay));
  box-shadow:
    var(--shadow-overlay),
    0 0 40px var(--edge-glow),
    inset 0 1px 0 var(--edge-light);
}

/* popover.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="popover-arrow"] {
    fill: var(--elevated);
  }
}
